node.script:
function OnStart(so_self, length)
{
	local kvs = StageObject_GetKeyValueStore(so_self);
	local pos = StageObject_GetPosition(so_self);
	KeyValueStore_SetKeyValueFloat3(kvs, "base_pos", pos[0], pos[1], pos[2]);
	Actor_SetActorFlag(so_self, "STATIC", false);
}

function OnUpdate(so_actor, time_key, length)
{
	local kvs = StageObject_GetKeyValueStore(so_actor);
	local base_pos = KeyValueStore_GetKeyValue(kvs, "base_pos");
	StageObject_SetPosition(so_actor, base_pos[0], base_pos[1], base_pos[2]);

	local offset = cos(2 * PI * time_key / length);
	offset *= offset;
	local new_pos = StageObject_GetPositionWithOffset(so_actor, 0, 10 * offset, 0);
	StageObject_SetPosition(so_actor, new_pos[0], new_pos[1], new_pos[2]);
}

node.interaction_0_script_to_run_on_interacti:
function OnInteraction(so_self, so_activator)
{
	Game_SetCinemaMode(true, true);

	local script_start = @"
	Game_SetCinemaMode(true);
	Actor_SetActorFlag($so_activator, ""SOLID "", false);
	";

	script_start = string_replace(script_start, "$so_activator", so_activator.tostring());

	Game_SetStagePointOfInterestCompleted(so_self);

	Actor_QueueActionRunScript(so_activator, script_start);

	Actor_QueueActionPlayAnimation(so_activator, "tool_unequip", false);

	if (Actor_HasInteraction(so_self, "custom_stage_enter"))
		Actor_InteractWithInteraction(so_self, so_activator, "custom_stage_enter");

	// end cinematic hack
	local is_quest_end = Game_GetWorldState("UNDERWORLD", "QUEST_END_CINEMATIC");

	if (is_quest_end == "1") {
		Game_SetWorldState("UNDERWORLD", "QUEST_END_CINEMATIC", "0");
		return;
	}

	local player_index = Game_GetPlayerIndexByActor(so_activator);
	local secs = 0.7*player_index;
	if (secs > 0)
		Actor_QueueActionWait(so_activator, secs);

   // local pos_from = StageObject_GetPositionWithOffset(so_self, 0, 0, 0);
   // local pos_to = StageObject_GetPositionWithOffset(so_self, 0, -120, 0);
   // StageObject_SetPosition(so_activator, pos_from[0], pos_from[1], pos_from[2]);

	// TODO: should set the first position of the path.

	local kvs = StageObject_GetKeyValueStore(so_self);
	Actor_QueueActionMoveAlongKeyValueStorePath(so_activator, kvs, "path_come_out");
	//Actor_QueueActionMove(so_activator, pos_to[0]+player_index*15, pos_to[1]+player_index*35, pos_to[2]);

	Actor_QueueActionPlayAnimation(so_activator, "tool_equip", true);

	local script_end = @"
		Game_SetCinemaMode(false);
		Actor_SetActorFlag($so_activator, ""SOLID"", true);
		";

	script_end = string_replace(script_end, "$so_activator", so_activator.tostring());

	Actor_QueueActionRunScript(so_activator, script_end);
}

node.interaction_1_script_to_run_on_interacti:
function OnInteraction(so_self, so_activator)
{
	Game_SetCinemaMode(true);

	local script_start = @"
		Game_SetCinemaMode(true);
		Actor_SetActorFlag($so_activator, ""SOLID"", false);
		";

	Game_SetStagePointOfInterestCompleted(so_self);

	script_start = string_replace(script_start, "$so_activator", so_activator.tostring());

	Actor_QueueActionRunScript(so_activator, script_start);

	Actor_QueueActionPlayAnimation(so_activator, "tool_unequip", false);

	local kvs = StageObject_GetKeyValueStore(so_self);
	Actor_QueueActionMoveAlongKeyValueStorePath(so_activator, kvs, "path_go_in");
	//local pos_from = StageObject_GetPositionWithOffset(so_self, 160, 0, 0);
	//local pos_to = StageObject_GetPositionWithOffset(so_self, 60, 0, 0);
	//Actor_QueueActionMove(so_activator, pos_from[0], pos_from[1], pos_from[2]);
	//Actor_QueueActionMove(so_activator, pos_to[0], pos_to[1], pos_to[2]);

	local script_end = @"
		//Game_SetCinemaMode(false);
		//Actor_SetActorFlag($so_activator, ""SOLID"", true);
		";

	script_end = string_replace(script_end, "$so_activator", so_activator.tostring());

	Actor_QueueActionRunScript(so_activator, script_end);
	if (Actor_HasInteraction(so_self, "custom_enter"))
		Actor_InteractWithInteraction(so_self, so_activator, "custom_enter");

	Game_SetScreenFadeOutWithCommand(0.6, "travel_to_stage", so_self, 0.65);
}
